insert into public.bible_verses (id, book_key, book_name, chapter, verse, content, sort_order)
values
('isa-18-3','isa','이사야',18,3,'세상의 모든 거민, 지상에 사는 너희여 산들 위에 기치를 세우거든 너희는 보고 나팔을 불거든 너희는 들을지니라',18001),
('isa-18-4','isa','이사야',18,4,'여호와께서 내게 이르시되 내가 나의 처소에서 조용히 감찰함이 쬐이는 일광 같고 가을 더위에 운무 같도다',18002),
('isa-18-5','isa','이사야',18,5,'추수하기 전에 꽃이 떨어지고 포도가 맺혀 익어갈 때에 내가 낫으로 그 연한 가지를 베며 퍼진 가지를 찍어 버려서',18003),
('isa-18-6','isa','이사야',18,6,'산의 독수리들과 땅의 들짐승들에게 던져 주리니 산의 독수리들이 그것으로 여름을 지내며 땅의 들짐승들이 다 그것으로 겨울을 지내리라 하셨음이라',18004),
('isa-18-7','isa','이사야',18,7,'그 때에 강들이 흘러 나누인 나라의 장대하고 준수한 백성 곧 시초부터 두려움이 되며 강성하여 대적을 밟는 백성이 만군의 여호와께 드릴 예물을 가지고 만군의 여호와의 이름을 두신 곳 시온 산에 이르리라',18005),
('isa-19-1','isa','이사야',19,1,'애굽에 관한 경고라. 보라 여호와께서 빠른 구름을 타고 애굽에 임하시리니 애굽의 우상들이 그 앞에서 떨겠고 애굽인의 마음이 그 속에서 녹으리로다',18006),
('isa-19-2','isa','이사야',19,2,'내가 애굽인을 격동하여 애굽인을 치리니 그들이 각기 형제를 치며 각기 이웃을 칠 것이요 성읍이 성읍을 치며 나라가 나라를 칠 것이며',18007),
('isa-19-3','isa','이사야',19,3,'애굽인의 정신이 그 속에서 쇠약할 것이요 그의 계획을 내가 깨뜨리리니 그들이 우상과 마술사와 신접한 자와 요술객에게 물으리로다',18008),
('isa-19-4','isa','이사야',19,4,'그가 애굽인을 잔인한 주인의 손에 붙이리니 포학한 왕이 그들을 다스리리라 주 만군의 여호와의 말씀이니라',18009),
('isa-19-5','isa','이사야',19,5,'바닷물이 없어지겠고 강이 잦아서 마르겠고',18010),
('isa-19-6','isa','이사야',19,6,'강들에서는 악취가 나겠고 애굽의 강물은 줄어들고 마르므로 갈대와 부들이 시들겠으며',18011),
('isa-19-7','isa','이사야',19,7,'나일 가까운 곳 나일 언덕의 초장과 나일 강 가까운 곡식 밭이 다 말라서 날려가 없어질 것이며',18012),
('isa-19-8','isa','이사야',19,8,'어부들은 탄식하며 나일 강에 낚시를 던지는 자마다 슬퍼하며 물 위에 그물을 치는 자는 피곤할 것이며',18013),
('isa-19-9','isa','이사야',19,9,'세마포를 만드는 자와 베 짜는 자들이 수치를 당할 것이며',18014),
('isa-19-10','isa','이사야',19,10,'그의 기둥이 부숴지고 품꾼들이 다 마음에 근심하리라',18015),
('isa-19-11','isa','이사야',19,11,'소안의 방백은 어리석었고 바로의 가장 지혜로운 모사의 책략은 우둔하여졌으니 너희가 어떻게 바로에게 이르기를 나는 지혜로운 자들의 자손이라 나는 옛 왕들의 후예라 할 수 있으랴',18016),
('isa-19-12','isa','이사야',19,12,'너의 지혜로운 자가 어디 있느냐 그들이 만군의 여호와께서 애굽에 대하여 정하신 뜻을 알 것이요 곧 네게 말할 것이니라',18017),
('isa-19-13','isa','이사야',19,13,'소안의 방백들은 어리석었고 놉의 방백들은 미혹되었도다 그들은 애굽 종족들의 모퉁잇돌이거늘 애굽을 그릇 가게 하였도다',18018),
('isa-19-14','isa','이사야',19,14,'여호와께서 그 가운데 어지러운 마음을 섞으셨으므로 그들이 애굽을 매사에 잘못 가게 함이 취한 자가 토하면서 비틀거림 같게 하였으니',18019),
('isa-19-15','isa','이사야',19,15,'애굽에서 머리나 꼬리며 종려나무 가지나 갈대가 아무 할 일이 없으리라',18020),
('isa-19-16','isa','이사야',19,16,'그 날에 애굽이 부녀와 같을 것이라 그들이 만군의 여호와께서 흔드시는 손이 그들 위에 흔들림으로 말미암아 떨며 두려워할 것이며',18021),
('isa-19-17','isa','이사야',19,17,'유다의 땅은 애굽의 두려움이 되리니 이는 만군의 여호와께서 애굽에 대하여 정하신 계획으로 말미암음이라 그 소문을 듣는 자마다 떨리라',18022),
('isa-19-18','isa','이사야',19,18,'그 날에 애굽 땅에 가나안 방언을 말하며 만군의 여호와를 가리켜 맹세하는 다섯 성읍이 있을 것이며 그 중 하나를 멸망의 성읍이라 칭하리라',18023),
('isa-19-19','isa','이사야',19,19,'그 날에 애굽 땅 중앙에는 여호와를 위하여 제단이 있겠고 그 변경에는 여호와를 위하여 기둥이 있을 것이요',18024),
('isa-19-20','isa','이사야',19,20,'이것이 애굽 땅에서 만군의 여호와를 위하여 징조와 증거가 되리니 이는 그들이 그 압박하는 자들로 말미암아 여호와께 부르짖겠고 여호와께서는 그들에게 한 구원자이자 보호자를 보내사 그들을 건지실 것임이라',18025),
('isa-19-21','isa','이사야',19,21,'여호와께서 자기를 애굽에 알게 하시리니 그 날에 애굽이 여호와를 알고 제물과 예물을 그에게 드리고 경배할 것이요 여호와께 서원하고 그대로 행하리라',18026),
('isa-19-22','isa','이사야',19,22,'여호와께서 애굽을 치실지라도 치시고는 고치실 것이므로 그들이 여호와께로 돌아올 것이라 여호와께서 그들의 간구함을 들으시고 그들을 고쳐 주시리라',18027),
('isa-19-23','isa','이사야',19,23,'그 날에 애굽에서 앗수르로 통하는 대로가 있어 앗수르 사람은 애굽으로 가겠고 애굽 사람은 앗수르로 갈 것이며 애굽 사람이 앗수르 사람과 함께 경배하리라',18028),
('isa-19-24','isa','이사야',19,24,'그 날에 이스라엘이 애굽 및 앗수르와 더불어 셋이 세계 중에 복이 되리니',18029),
('isa-19-25','isa','이사야',19,25,'이는 만군의 여호와께서 복 주시며 이르시되 내 백성 애굽이여, 내 손으로 지은 앗수르여, 나의 기업 이스라엘이여, 복이 있을지어다 하실 것임이라',18030),
('isa-20-1','isa','이사야',20,1,'앗수르의 사르곤 왕이 다르단을 아스돗으로 보내매 그가 와서 아스돗을 쳐서 취하던 해니라',18031),
('isa-20-2','isa','이사야',20,2,'그 때에 여호와께서 아모스의 아들 이사야에게 말씀하여 이르시되 갈지어다 네 허리에서 베를 끄르고 네 발에서 신을 벗을지니라 하시매 그가 그대로 하여 벗은 몸과 벗은 발로 다니니라',18032),
('isa-20-3','isa','이사야',20,3,'여호와께서 이르시되 나의 종 이사야가 삼 년 동안 벗은 몸과 벗은 발로 다니며 애굽과 구스에 대하여 징조와 예표가 되었느니라',18033),
('isa-20-4','isa','이사야',20,4,'이와 같이 애굽의 포로와 구스의 사로잡힌 자가 앗수르 왕에게 끌려갈 때에 젊은 자나 늙은 자가 다 벗은 몸과 벗은 발로 볼기까지 드러내어 애굽의 수치를 보이리니',18034),
('isa-20-5','isa','이사야',20,5,'그들이 바라던 구스와 자랑하던 애굽으로 말미암아 그들이 놀라고 부끄러워할 것이라',18035),
('isa-20-6','isa','이사야',20,6,'그 날에 이 해변 주민이 말하기를 우리가 믿던 나라 곧 우리가 앗수르 왕에게서 벗어나기를 바라고 달려가서 도움을 구하던 나라가 이같이 되었은즉 우리가 어찌 능히 피하리요 하리라',18036),
('isa-21-1','isa','이사야',21,1,'해변 광야에 관한 경고라. 적병이 광야에서, 두려운 땅에서 네겝 회오리바람 같이 몰려왔도다',18037),
('isa-21-2','isa','이사야',21,2,'혹독한 묵시가 내게 보였도다 속이는 자는 속이고 약탈하는 자는 약탈하도다 엘람이여 올라가고 메대여 에워싸라 그의 모든 탄식을 내가 그치게 하였노라 하시도다',18038),
('isa-21-3','isa','이사야',21,3,'이러므로 나의 요통이 심하여 해산이 임박한 여인의 고통 같은 고통이 나를 엄습하였으므로 내가 괴로워서 듣지 못하며 놀라서 보지 못하도다',18039),
('isa-21-4','isa','이사야',21,4,'내 마음이 어지럽고 두려움이 나를 놀라게 하며 희망의 서광이 변하여 내게 떨림이 되도다',18040),
('isa-21-5','isa','이사야',21,5,'그들이 식탁을 베풀고 파수꾼을 세우고 먹고 마시도다 너희 고관들아 일어나 방패에 기름을 바를지어다',18041),
('isa-21-6','isa','이사야',21,6,'주께서 내게 이르시되 가서 파수꾼을 세우고 그가 보는 것을 보고하게 하되',18042),
('isa-21-7','isa','이사야',21,7,'마병대가 쌍쌍이 오는 것과 나귀 떼와 낙타 떼를 보거든 귀 기울여 자세히 들으라 하셨더니',18043),
('isa-21-8','isa','이사야',21,8,'파수꾼이 사자 같이 부르짖기를 주여 내가 낮에 늘 망대에 서 있었고 밤이 새도록 파수하는 곳에 있었더니',18044),
('isa-21-9','isa','이사야',21,9,'보소서 마병대가 쌍쌍이 오나이다 하니 그가 대답하여 이르시되 함락되었도다 함락되었도다 바벨론이여 그들이 조각한 신상들이 다 부서져 땅에 떨어졌도다 하시도다',18045),
('isa-21-10','isa','이사야',21,10,'내가 짓밟은 너여, 내가 타작한 너여, 내가 이스라엘의 하나님 만군의 여호와께 들은 대로 너희에게 전하였노라',18046),
('isa-21-11','isa','이사야',21,11,'두마에 관한 경고라. 사람이 세일에서 나를 부르되 파수꾼이여 밤이 어떻게 되었느냐 파수꾼이여 밤이 어떻게 되었느냐',18047),
('isa-21-12','isa','이사야',21,12,'파수꾼이 이르되 아침이 오나니 밤도 오리라 네가 물으려거든 물으라 너희는 돌아올지니라 하더라',18048),
('isa-21-13','isa','이사야',21,13,'아라비아에 관한 경고라. 드단 대상들이여 너희가 아라비아 수풀에서 유숙하리라',18049),
('isa-21-14','isa','이사야',21,14,'데마 땅의 주민들아 물을 가져다가 목마른 자에게 주고 떡을 가지고 도피하는 자를 영접2)하라',18050),
('isa-21-15','isa','이사야',21,15,'그들이 칼날을 피하며 뺀 칼과 당긴 활과 전쟁의 어려움에서 도망하였음이니라',18051),
('isa-21-16','isa','이사야',21,16,'주께서 이같이 내게 이르시되 품꾼의 정한 기한 같이 일 년 내에 게달의 영광이 다 쇠멸하리니',18052),
('isa-21-17','isa','이사야',21,17,'게달 자손 중 활 가진 용사의 남은 수가 적으리라 하시니라 이스라엘의 하나님 여호와의 말씀이니라',18053),
('isa-22-1','isa','이사야',22,1,'환상의 골짜기에 관한 경고라. 네가 지붕에 올라감은 어찌함인고',18054),
('isa-22-2','isa','이사야',22,2,'소란하며 떠들던 성, 즐거워하던 고을이여 너의 죽임을 당한 자들은 칼에 죽은 것도 아니요 전쟁에 사망한 것도 아니라',18055),
('isa-22-3','isa','이사야',22,3,'너의 관원들도 다 함께 도망하였다가 활을 버리고 결박을 당하였고 너의 멀리 도망한 자들도 발견되어 다 함께 결박을 당하였도다',18056),
('isa-22-4','isa','이사야',22,4,'그러므로 내가 말하노니 돌이켜 나를 보지 말지어다 나는 슬피 통곡하겠노라 내 딸 백성이 패망하였음으로 말미암아 나를 위로하려고 힘쓰지 말지니라',18057),
('isa-22-5','isa','이사야',22,5,'환상의 골짜기에 주 만군의 여호와께로부터 이르는 소란과 밟힘과 혼란의 날이여 성벽의 무너뜨림과 산악에 사무쳐 부르짖는 소리로다',18058),
('isa-22-6','isa','이사야',22,6,'엘람 사람은 화살통을 메었고 병거 탄 자와 마병이 함께 하였고 기르 사람은 방패를 드러냈으니',18059),
('isa-22-7','isa','이사야',22,7,'병거는 네 아름다운 골짜기에 가득하였고 마병은 성문에 정렬되었도다',18060),
('isa-22-8','isa','이사야',22,8,'그가 유다에게 덮였던 것을 벗기매 그 날에야 네가 수풀 곳간의 병기를 바라보았고',18061),
('isa-22-9','isa','이사야',22,9,'너희가 다윗 성의 무너진 곳이 많은 것도 보며 너희가 아랫못의 물도 모으며',18062),
('isa-22-10','isa','이사야',22,10,'또 예루살렘의 가옥을 계수하며 그 가옥을 헐어 성벽을 견고하게도 하며',18063),
('isa-22-11','isa','이사야',22,11,'너희가 또 옛 못의 물을 위하여 두 성벽 사이에 저수지를 만들었느니라 그러나 너희가 이를 행하신 이를 앙망하지 아니하였고 이 일을 옛적부터 경영하신 이를 공경하지 아니하였느니라',18064),
('isa-22-12','isa','이사야',22,12,'그 날에 주 만군의 여호와께서 명령하사 통곡하며 애곡하며 머리 털을 뜯으며 굵은 베를 띠라 하셨거늘',18065),
('isa-22-13','isa','이사야',22,13,'너희가 기뻐하며 즐거워하여 소를 죽이고 양을 잡아 고기를 먹고 포도주를 마시면서 내일 죽으리니 먹고 마시자 하는도다',18066),
